    for(const key of ['privacyPolicy','licensesPage','legalNotice'])texts[key]='<section lang="de">'+texts[key]+'</section>';
    strings['German help, ADVISOR and legal information now declare their language for correct pronunciation and text handling.']='Deutsche Hilfe, ADVISOR und Rechtstexte kennzeichnen ihre Sprache für korrekte Aussprache und Textdarstellung.';
